struct Version: Equatable { let effective: Date; let terms: Terms }   // value snapshot
struct Contract {                                                     // continuity
    private(set) var history: [Version] = []
    var current: Version { history[history.count - 1] }
    func asOf(_ on: Date) -> Version? {
        history.last { $0.effective <= on }        // nil = Missing Version
    }
    mutating func amend(effective: Date, working: Terms) {
        let at = history.firstIndex { $0.effective > effective } ?? history.endIndex
        history.insert(Version(effective: effective, terms: working), at: at)
    }
}
